ALTER VIEW public.administrator_sessions ALTER COLUMN created_at SET DEFAULT clock_timestamp();

CREATE FUNCTION geo.write_administrator_sessions() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,geo AS $body$
DECLARE r text; current_row public.administrator_sessions%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    SELECT id,administrator_id,token_hash,active,created_at,invalidated_at INTO current_row FROM geo.data_administrator_sessions WHERE id=OLD.id FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF current_row IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'concurrent modification of administrator_sessions; retry transaction' USING ERRCODE='40001';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN
    DELETE FROM geo.registry_administrator_sessions WHERE id=OLD.id;
    RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id) THEN
    RAISE EXCEPTION 'immutable identity in administrator_sessions' USING ERRCODE='23514';
  END IF;
  SELECT geo_region INTO STRICT r FROM geo.registry_administrators WHERE id=NEW.administrator_id FOR KEY SHARE;
  IF TG_OP='INSERT' THEN
    INSERT INTO geo.registry_administrator_sessions (id,administrator_id,geo_region)
      VALUES (NEW.id,NEW.administrator_id,r);
    INSERT INTO geo.data_administrator_sessions (id,administrator_id,token_hash,active,created_at,invalidated_at,placement_region)
      VALUES (NEW.id,NEW.administrator_id,NEW.token_hash,NEW.active,NEW.created_at,NEW.invalidated_at,r);
  ELSE
    UPDATE geo.registry_administrator_sessions SET id=NEW.id,administrator_id=NEW.administrator_id,geo_region=r WHERE id=OLD.id;
    UPDATE geo.data_administrator_sessions SET id=NEW.id,administrator_id=NEW.administrator_id,token_hash=NEW.token_hash,active=NEW.active,created_at=NEW.created_at,invalidated_at=NEW.invalidated_at WHERE id=NEW.id AND placement_region=r;
  END IF;
  RETURN NEW;
EXCEPTION WHEN no_data_found THEN
  RAISE EXCEPTION 'referenced owner does not exist for administrator_sessions' USING ERRCODE='23503';
END
$body$;
CREATE TRIGGER write_administrator_sessions INSTEAD OF INSERT OR UPDATE OR DELETE ON public.administrator_sessions FOR EACH ROW EXECUTE FUNCTION geo.write_administrator_sessions();

