CREATE TABLE geo.data_realmojis_europe PARTITION OF geo.data_realmojis FOR VALUES IN ('europe') TABLESPACE local_europe SPLIT INTO 1 TABLETS;

CREATE TABLE geo.data_realmojis_america PARTITION OF geo.data_realmojis FOR VALUES IN ('america') TABLESPACE local_america SPLIT INTO 1 TABLETS;

CREATE INDEX data_realmojis_post_id_idx ON geo.data_realmojis (post_id);

CREATE INDEX data_realmojis_reactor_id_idx ON geo.data_realmojis (reactor_id);

CREATE VIEW public.realmojis AS SELECT id,post_id,reactor_id,image_id,reaction_type,created_at,replaced_at,deleted_at FROM geo.data_realmojis;

CREATE FUNCTION geo.write_realmojis() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,geo AS $body$
DECLARE r text; current_row public.realmojis%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    SELECT id,post_id,reactor_id,image_id,reaction_type,created_at,replaced_at,deleted_at INTO current_row FROM geo.data_realmojis WHERE id=OLD.id FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF current_row IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'concurrent modification of realmojis; retry transaction' USING ERRCODE='40001';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN
    DELETE FROM geo.registry_realmojis WHERE id=OLD.id;
    RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id) THEN
    RAISE EXCEPTION 'immutable identity in realmojis' USING ERRCODE='23514';
  END IF;
  SELECT geo_region INTO STRICT r FROM geo.registry_users WHERE id=NEW.reactor_id FOR KEY SHARE;
  IF TG_OP='INSERT' THEN
    INSERT INTO geo.registry_realmojis (id,post_id,reactor_id,replaced_at,deleted_at,geo_region)
      VALUES (NEW.id,NEW.post_id,NEW.reactor_id,NEW.replaced_at,NEW.deleted_at,r);
    INSERT INTO geo.data_realmojis (id,post_id,reactor_id,image_id,reaction_type,created_at,replaced_at,deleted_at,placement_region)
      VALUES (NEW.id,NEW.post_id,NEW.reactor_id,NEW.image_id,NEW.reaction_type,NEW.created_at,NEW.replaced_at,NEW.deleted_at,r);
  ELSE
    UPDATE geo.registry_realmojis SET id=NEW.id,post_id=NEW.post_id,reactor_id=NEW.reactor_id,replaced_at=NEW.replaced_at,deleted_at=NEW.deleted_at,geo_region=r WHERE id=OLD.id;
    UPDATE geo.data_realmojis SET id=NEW.id,post_id=NEW.post_id,reactor_id=NEW.reactor_id,image_id=NEW.image_id,reaction_type=NEW.reaction_type,created_at=NEW.created_at,replaced_at=NEW.replaced_at,deleted_at=NEW.deleted_at WHERE id=NEW.id AND placement_region=r;
  END IF;
  RETURN NEW;
EXCEPTION WHEN no_data_found THEN
  RAISE EXCEPTION 'referenced owner does not exist for realmojis' USING ERRCODE='23503';
END
$body$;
CREATE TRIGGER write_realmojis INSTEAD OF INSERT OR UPDATE OR DELETE ON public.realmojis FOR EACH ROW EXECUTE FUNCTION geo.write_realmojis();

