CREATE FUNCTION geo.write_comments() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,geo AS $body$
DECLARE r text; current_row public.comments%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    SELECT id,post_id,author_id,body,created_at,deleted_at INTO current_row FROM geo.data_comments WHERE id=OLD.id FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
