  END IF;
  IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id) THEN
    RAISE EXCEPTION 'immutable identity in comments' USING ERRCODE='23514';
  END IF;
  SELECT geo_region INTO STRICT r FROM geo.registry_users WHERE id=NEW.author_id FOR KEY SHARE;
  IF TG_OP='INSERT' THEN
    INSERT INTO geo.registry_comments (id,post_id,author_id,geo_region)
      VALUES (NEW.id,NEW.post_id,NEW.author_id,r);
    INSERT INTO geo.data_comments (id,post_id,author_id,body,created_at,deleted_at,placement_region)
      VALUES (NEW.id,NEW.post_id,NEW.author_id,NEW.body,NEW.created_at,NEW.deleted_at,r);
