CREATE FUNCTION geo.write_notifications() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,geo AS $body$
DECLARE r text; current_row public.notifications%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    SELECT id,user_id,posting_window_id,created_at INTO current_row FROM geo.data_notifications WHERE id=OLD.id FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF current_row IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'concurrent modification of notifications; retry transaction' USING ERRCODE='40001';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN
    DELETE FROM geo.registry_notifications WHERE id=OLD.id;
    RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND (NEW.id IS DISTINCT FROM OLD.id) THEN
    RAISE EXCEPTION 'immutable identity in notifications' USING ERRCODE='23514';
  END IF;
  SELECT geo_region INTO STRICT r FROM geo.registry_users WHERE id=NEW.user_id FOR KEY SHARE;
  IF TG_OP='INSERT' THEN
    INSERT INTO geo.registry_notifications (id,user_id,posting_window_id,geo_region)
      VALUES (NEW.id,NEW.user_id,NEW.posting_window_id,r);
    INSERT INTO geo.data_notifications (id,user_id,posting_window_id,created_at,placement_region)
      VALUES (NEW.id,NEW.user_id,NEW.posting_window_id,NEW.created_at,r);
  ELSE
    UPDATE geo.registry_notifications SET id=NEW.id,user_id=NEW.user_id,posting_window_id=NEW.posting_window_id,geo_region=r WHERE id=OLD.id;
    UPDATE geo.data_notifications SET id=NEW.id,user_id=NEW.user_id,posting_window_id=NEW.posting_window_id,created_at=NEW.created_at WHERE id=NEW.id AND placement_region=r;
  END IF;
  RETURN NEW;
EXCEPTION WHEN no_data_found THEN
  RAISE EXCEPTION 'referenced owner does not exist for notifications' USING ERRCODE='23503';
END
$body$;
CREATE TRIGGER write_notifications INSTEAD OF INSERT OR UPDATE OR DELETE ON public.notifications FOR EACH ROW EXECUTE FUNCTION geo.write_notifications();

CREATE TABLE geo.data_ip_bans (
  ip text NOT NULL,
  banned_until timestamptz NOT NULL,
  created_at timestamptz NOT NULL,
  placement_region text NOT NULL CHECK (placement_region IN ('asia','europe','america')),
  PRIMARY KEY (placement_region,ip),
  FOREIGN KEY (ip,placement_region) REFERENCES geo.registry_ip_bans (ip,geo_region) ON UPDATE CASCADE ON DELETE CASCADE) PARTITION BY LIST(placement_region);

CREATE TABLE geo.data_ip_bans_asia PARTITION OF geo.data_ip_bans FOR VALUES IN ('asia') TABLESPACE local_asia SPLIT INTO 1 TABLETS;

CREATE TABLE geo.data_ip_bans_europe PARTITION OF geo.data_ip_bans FOR VALUES IN ('europe') TABLESPACE local_europe SPLIT INTO 1 TABLETS;

CREATE TABLE geo.data_ip_bans_america PARTITION OF geo.data_ip_bans FOR VALUES IN ('america') TABLESPACE local_america SPLIT INTO 1 TABLETS;

CREATE VIEW public.ip_bans AS SELECT ip,banned_until,created_at FROM geo.data_ip_bans;

ALTER VIEW public.ip_bans ALTER COLUMN created_at SET DEFAULT clock_timestamp();

CREATE FUNCTION geo.write_ip_bans() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public,geo AS $body$
DECLARE r text; current_row public.ip_bans%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    SELECT ip,banned_until,created_at INTO current_row FROM geo.data_ip_bans WHERE ip=OLD.ip FOR UPDATE;
    IF NOT FOUND THEN RETURN NULL; END IF;
    IF current_row IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'concurrent modification of ip_bans; retry transaction' USING ERRCODE='40001';
    END IF;
  END IF;
  IF TG_OP='DELETE' THEN
    DELETE FROM geo.registry_ip_bans WHERE ip=OLD.ip;
    RETURN OLD;
  END IF;
  IF TG_OP='UPDATE' AND (NEW.ip IS DISTINCT FROM OLD.ip) THEN
    RAISE EXCEPTION 'immutable identity in ip_bans' USING ERRCODE='23514';
  END IF;
  r := 'asia'; -- regionless control-plane entity
  IF TG_OP='INSERT' THEN
    INSERT INTO geo.registry_ip_bans (ip,geo_region)
      VALUES (NEW.ip,r);
    INSERT INTO geo.data_ip_bans (ip,banned_until,created_at,placement_region)
      VALUES (NEW.ip,NEW.banned_until,NEW.created_at,r);
  ELSE
    UPDATE geo.registry_ip_bans SET ip=NEW.ip,geo_region=r WHERE ip=OLD.ip;
    UPDATE geo.data_ip_bans SET ip=NEW.ip,banned_until=NEW.banned_until,created_at=NEW.created_at WHERE ip=NEW.ip AND placement_region=r;
  END IF;
  RETURN NEW;
EXCEPTION WHEN no_data_found THEN
  RAISE EXCEPTION 'referenced owner does not exist for ip_bans' USING ERRCODE='23503';
END
$body$;
CREATE TRIGGER write_ip_bans INSTEAD OF INSERT OR UPDATE OR DELETE ON public.ip_bans FOR EACH ROW EXECUTE FUNCTION geo.write_ip_bans();

-- A partitioned CREATE INDEX does not inherit each child's tablespace in YSQL.
-- Move every secondary child index explicitly; primary indexes already match.
SELECT format('ALTER INDEX %s SET TABLESPACE %I',i.indexrelid::regclass,t.spcname)
FROM pg_index i JOIN pg_class c ON c.oid=i.indrelid
JOIN pg_namespace n ON n.oid=c.relnamespace
JOIN pg_tablespace t ON t.oid=c.reltablespace
WHERE n.nspname='geo' AND c.relkind='r' AND NOT i.indisprimary
  AND t.spcname IN ('local_asia','local_europe','local_america')
\gexec

